import { Project } from '../../src'

describe('Keys registry tests', () => {
    test('Keys should be registered from the metadata dir on build', async () => {
        const project = new Project()

        // Fluent admin role
        const admin = project.addFile({
            path: 'src/fluent/admin.now.ts',
            content: `import { Role } from '@servicenow/sdk/core'
Role({
    name: 'admin',
    containsRoles: ['manager'],
})`,
        })

        // XML manager role
        await project
            .addFile({
                path: 'metadata/update/manager.xml',
                content: `<?xml version="1.0"?>
<record_update>
  <sys_user_role action="INSERT_OR_UPDATE">
    <sys_id>22222</sys_id>
    <name>manager</name>
    <suffix>manager</suffix>
  </sys_user_role>
</record_update>`,
            })
            .getRecords() // TODO: It sucks that we have to call getRecords() on this file to make sure our keys registry is complete

        const records = await admin.getRecords()
        expect(records.query()).toHaveLength(2)

        const adminRole = records.get('sys_user_role', { name: 'admin' })
        expect(adminRole).toBeDefined()

        const m2m = records.get('sys_user_role_contains', { role: adminRole.getId(), contains: '22222' })
        expect(m2m).toBeDefined()

        const keys = project.getKeys()
        expect(keys.getValue()).toMatchObject({
            explicit: {},
            deleted: {},
            composite: [
                {
                    table: 'sys_user_role',
                    key: { name: 'manager' },
                },
                {
                    table: 'sys_user_role',
                    key: { name: 'admin' },
                },
                {
                    table: 'sys_user_role_contains',
                    key: {
                        role: { key: { name: 'admin' } },
                        contains: { key: { name: 'manager' } },
                    },
                },
            ],
        })
    })

    test('Resolving conflict between metadata dir and Fluent code by removing the Fluent code', async () => {
        const warnings: string[] = []
        const project = new Project({ logger: { ...console, warn: (msg) => warnings.push(msg) } })

        project.addFile({
            path: 'metadata/update/sys_user_role_12345.xml',
            content: `<?xml version="1.0"?>
<record_update>
  <sys_user_role action="INSERT_OR_UPDATE">
    <sys_id>12345</sys_id>
    <name>test</name>
  </sys_user_role>
</record_update>`,
        })

        const fluentFile = project.addFile({
            path: 'src/fluent/role.now.ts',
            content: `import { Role } from '@servicenow/sdk/core'

Role({
    name: 'test'
})`,
        })

        async function check() {
            const records = (await project.getRecords()).query('sys_user_role')
            expect(records).toHaveLength(1)
            expect(records.filter((r) => r.getAction() === 'DELETE')).toHaveLength(0)
            expect(records[0].getId().getValue()).toBe('12345')

            const keys = project.getKeys().getValue()
            expect(keys.composite).toEqual([
                {
                    table: 'sys_user_role',
                    id: '12345',
                    key: { name: 'test' },
                },
            ])
        }

        await check()
        expect(warnings).toHaveLength(2)
        expect(warnings[0]).toBe(`Record "sys_user_role.12345" is defined 2 times in the project:
    1. src/fluent/role.now.ts:3
    2. metadata/update/sys_user_role_12345.xml`)

        // Remove the Fluent-defined role
        fluentFile.setContent('')
        warnings.length = 0

        await check()
        expect(warnings).toHaveLength(0)
    })

    test('Error when Fluent code uses an explicit key that is defined multiple times', async () => {
        const errors: string[] = []
        const project = new Project({ logger: { ...console, error: (msg) => errors.push(msg) } })

        project.addFile({
            path: 'src/fluent/role.now.ts',
            content: `import { ApplicationMenu, Property } from '@servicenow/sdk/core'

ApplicationMenu({
    $id: Now.ID['Menu 2'],
    title: 'Menu 2',
    hint: 'hint 2',
    description: 'This is a description',
    active: true,
})

Property({
    $id: Now.ID['Menu 2'],
    name: 'sn_example.employee.limit',
    value: 5,
    type: 'integer',
    description: 'Maximum number of employees',
})`,
        })

        await expect(project.getRecords()).rejects.toThrow('Found 1 duplicate explicit key(s) in the project.')
        expect(errors).toHaveLength(1)
        expect(errors[0]).toBe(`Explicit key "Menu 2" is defined multiple times in the project:
    1. [sys_app_application] src/fluent/role.now.ts:3
    2. [sys_properties] src/fluent/role.now.ts:11`)
    })
})
